$ErrorActionPreference='Stop'
Set-Location -LiteralPath 'C:\Users\ikuto\projects\conway-99-graph'
$taskPlanPath='acceleration/results/20261003_independent_review/wave41_transition_full_launch01/plan.json'
$taskPlanSha='6303a7f15043991e5e61d037142cba10645a3a551256139bd8bee3321283c954'
if((Get-FileHash -Algorithm SHA256 -LiteralPath $taskPlanPath).Hash.ToLower() -ne $taskPlanSha){throw 'PLAN_HASH'}
$taskPlan=Get-Content -Raw -LiteralPath $taskPlanPath|ConvertFrom-Json
$taskPins=[ordered]@{}
foreach($row in $taskPlan.immutable_inputs_sha256.PSObject.Properties){$taskHash=(Get-FileHash -Algorithm SHA256 -LiteralPath $row.Name).Hash.ToLower();if($taskHash -ne $row.Value){throw ('INPUT_HASH '+$row.Name)};$taskPins[$row.Name]=$taskHash}
$taskProtected=[ordered]@{'CLAIMS.yaml'=(Get-FileHash -Algorithm SHA256 -LiteralPath CLAIMS.yaml).Hash.ToLower();'.git/index'=(Get-FileHash -Algorithm SHA256 -LiteralPath .git/index).Hash.ToLower()}
foreach($row in $taskPlan.protected_execution_state_expected.PSObject.Properties){if($taskProtected[$row.Name] -ne $row.Value){throw ('PROTECTED_HASH '+$row.Name)}}
$taskObservationPath='acceleration/results/20261003_independent_review/wave41_transition_full_windows_observation01.json'
if((Get-FileHash -Algorithm SHA256 -LiteralPath $taskObservationPath).Hash.ToLower() -ne 'cc794b8f5ad66dc3f2559946c9779762813fdc06de048b7f031bb3a4512813a0'){throw 'OBSERVATION_HASH'}
$taskObservation=Get-Content -Raw -LiteralPath $taskObservationPath|ConvertFrom-Json
if(-not $taskObservation.launch_admissible -or @($taskObservation.unknown_recognized_workers).Count -ne 0){throw 'WORKER_OBSERVATION'}
$taskFreeMemory=([int64](Get-CimInstance Win32_OperatingSystem).FreePhysicalMemory*1024)
if($taskFreeMemory -lt 8GB){throw 'MEMORY'}
foreach($taskName in @('acceleration/results/20261003_independent_review/wave41_transition_full01','acceleration/results/20261003_independent_review/wave41_transition_full_supervision01')){if(Test-Path -LiteralPath $taskName){throw ('OUTPUT_EXISTS '+$taskName)}}
$taskHead=(& 'C:\Program Files\Git\cmd\git.exe' rev-parse HEAD).Trim()
if($LASTEXITCODE -ne 0 -or $taskHead -ne '00ffb6fdd7d91bd38269e1cc5e6b214ebf7591c8'){throw 'HEAD_HASH'}
$taskOut='acceleration/results/20261003_independent_review/wave41_transition_full_admission01.json'
if(Test-Path -LiteralPath $taskOut){throw 'ADMISSION_EXISTS'}
$taskRecord=[ordered]@{schema='WAVE41_EXACT_ACTUAL_METADATA_FULL_ADMISSION_V1';timestamp=[DateTimeOffset]::UtcNow.ToString('o');status='EXACT_ACTUAL_FULL_ADMISSION_PASS';plan=$taskPlanPath;plan_sha256=$taskPlanSha;inputs_sha256=$taskPins;immutable_members=$taskPins.Count;historical_protected_execution_state=$taskProtected;HEAD=$taskHead;windows_observation=$taskObservation.timestamp;windows_observation_sha256='cc794b8f5ad66dc3f2559946c9779762813fdc06de048b7f031bb3a4512813a0';free_memory_bytes=$taskFreeMemory;unknown_recognized_windows_workers=0;known_linux_peer=@{owner='/root/native_driver';invocation_id='a35b10ece04e44949555f4e51eaedf3e';exec_session=51637;source='acceleration/census_20261003_root_focused_chain_v2.py';source_sha256_prefix='fcf844';supervision='acceleration/results/20261003_root_focused_strict_lex_step1_census_supervision01';state='Owner directly reported active at10secondyield; not independently Linux-polled by this Windows checker';allocation_outer=300;allocation_worker=260};complete_closure='All complete calibration, exact ROOT gate and bound artifact maps are rehashed inside authorized unchanged150second full worker before acceptance; this admission hashes27directpins only.';mathematical_replays=0;ledger_mutations=0;index_mutations=0}
[IO.File]::WriteAllText((Join-Path (Get-Location) $taskOut),(($taskRecord|ConvertTo-Json -Depth 12)+"`n"),[Text.UTF8Encoding]::new($false))
[pscustomobject]@{status=$taskRecord.status;immutable_members=$taskPins.Count;sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $taskOut).Hash.ToLower()}|ConvertTo-Json -Compress
